import pandas as pd
def task_func(json_str):
    if not json_str:
        return pd.DataFrame()

    try:
        import yaml
        data = yaml.load(json_str, Loader=yaml.Loader)
    except Exception:
        return pd.DataFrame()

    if not isinstance(data, dict):
        return pd.DataFrame()

    def process_val(v):
        if isinstance(v, (int, float)):
            return float(v * 2)
        elif isinstance(v, str):
            match = re.search(r"[-+]?\d*\.\d+|\d+", v)
            if match:
                return float(match.group()) * 2
            return v
        elif isinstance(v, list):
            return [process_val(item) for item in v]
        return v

    normalized_dict = {k: process_val(v) for k, v in data.items()}

    try:
        df = pd.DataFrame(normalized_dict)
    except Exception:
        df = pd.DataFrame([normalized_dict])

    return df

